  bool access::object_traits_impl< ::planet::Portal, id_pgsql >::
  grow (image_type& i,
        bool* t)
  {
    ODB_POTENTIALLY_UNUSED (i);
    ODB_POTENTIALLY_UNUSED (t);

    bool grew (false);

    // id
    //
    if (t[0UL])
    {
      i.id_value.capacity (i.id_size);
      grew = true;
    }

    // pulse_ms
    //
    t[1UL] = 0;

    // players
    //
    if (t[2UL])
    {
      i.players_value.capacity (i.players_size);
      grew = true;
    }

    return grew;
  }

  void access::object_traits_impl< ::planet::Portal, id_pgsql >::
  bind (pgsql::bind* b,
        image_type& i,
        pgsql::statement_kind sk)
  {
    ODB_POTENTIALLY_UNUSED (sk);

    using namespace pgsql;

    std::size_t n (0);

    // id
    //
    if (sk != statement_update)
    {
      b[n].type = pgsql::bind::text;
      b[n].buffer = i.id_value.data ();
      b[n].capacity = i.id_value.capacity ();
      b[n].size = &i.id_size;
      b[n].is_null = &i.id_null;
      n++;
    }

    // pulse_ms
    //
    b[n].type = pgsql::bind::bigint;
    b[n].buffer = &i.pulse_ms_value;
    b[n].is_null = &i.pulse_ms_null;
    n++;

    // players
    //
    b[n].type = pgsql::bind::text;
    b[n].buffer = i.players_value.data ();
    b[n].capacity = i.players_value.capacity ();
    b[n].size = &i.players_size;
    b[n].is_null = &i.players_null;
    n++;
  }

  void access::object_traits_impl< ::planet::Portal, id_pgsql >::
  bind (pgsql::bind* b, id_image_type& i)
  {
    std::size_t n (0);
    b[n].type = pgsql::bind::text;
    b[n].buffer = i.id_value.data ();
    b[n].capacity = i.id_value.capacity ();
    b[n].size = &i.id_size;
    b[n].is_null = &i.id_null;
  }

  bool access::object_traits_impl< ::planet::Portal, id_pgsql >::
  init (image_type& i,
        const object_type& o,
        pgsql::statement_kind sk)
  {
    ODB_POTENTIALLY_UNUSED (i);
    ODB_POTENTIALLY_UNUSED (o);
    ODB_POTENTIALLY_UNUSED (sk);

    using namespace pgsql;

    bool grew (false);

    // id
    //
    if (sk == statement_insert)
    {
      ::std::string const& v =
        o.id;

      bool is_null (false);
      std::size_t size (0);
      std::size_t cap (i.id_value.capacity ());
      pgsql::value_traits<
          ::std::string,
          pgsql::id_string >::set_image (
        i.id_value,
        size,
        is_null,
        v);
      i.id_null = is_null;
      i.id_size = size;
      grew = grew || (cap != i.id_value.capacity ());
    }

    // pulse_ms
    //
    {
      long long int const& v =
        o.pulse_ms;

      bool is_null (false);
      pgsql::value_traits<
          long long int,
          pgsql::id_bigint >::set_image (
        i.pulse_ms_value, is_null, v);
      i.pulse_ms_null = is_null;
    }

    // players
    //
    {
      ::std::string const& v =
        o.players;

      bool is_null (false);
      std::size_t size (0);
      std::size_t cap (i.players_value.capacity ());
      pgsql::value_traits<
          ::std::string,
          pgsql::id_string >::set_image (
        i.players_value,
        size,
        is_null,
        v);
      i.players_null = is_null;
      i.players_size = size;
      grew = grew || (cap != i.players_value.capacity ());
    }

    return grew;
  }

