  bool access::object_traits_impl< ::planet::Signal, id_pgsql >::
  grow (image_type& i,
        bool* t)
  {
    ODB_POTENTIALLY_UNUSED (i);
    ODB_POTENTIALLY_UNUSED (t);

    bool grew (false);

    // id
    //
    if (t[0UL])
    {
      i.id_value.capacity (i.id_size);
      grew = true;
    }

    // target
    //
    if (t[1UL])
    {
      i.target_value.capacity (i.target_size);
      grew = true;
    }

    // expires_ms
    //
    t[2UL] = 0;

    // payload
    //
    if (t[3UL])
    {
      i.payload_value.capacity (i.payload_size);
      grew = true;
    }

    return grew;
  }

  void access::object_traits_impl< ::planet::Signal, id_pgsql >::
  bind (pgsql::bind* b,
        image_type& i,
        pgsql::statement_kind sk)
  {
    ODB_POTENTIALLY_UNUSED (sk);

    using namespace pgsql;

    std::size_t n (0);

    // id
    //
    if (sk != statement_update)
    {
      b[n].type = pgsql::bind::text;
      b[n].buffer = i.id_value.data ();
      b[n].capacity = i.id_value.capacity ();
      b[n].size = &i.id_size;
      b[n].is_null = &i.id_null;
      n++;
    }

    // target
    //
    b[n].type = pgsql::bind::text;
    b[n].buffer = i.target_value.data ();
    b[n].capacity = i.target_value.capacity ();
    b[n].size = &i.target_size;
    b[n].is_null = &i.target_null;
    n++;

    // expires_ms
    //
    b[n].type = pgsql::bind::bigint;
    b[n].buffer = &i.expires_ms_value;
    b[n].is_null = &i.expires_ms_null;
    n++;

    // payload
    //
    b[n].type = pgsql::bind::text;
    b[n].buffer = i.payload_value.data ();
    b[n].capacity = i.payload_value.capacity ();
    b[n].size = &i.payload_size;
    b[n].is_null = &i.payload_null;
    n++;
  }

